def _install_component(self, component, build_dir=None):
    build_dir = build_dir or self.build_dir or self._conanfile.build_folder
    arg_list = join_arguments([
        "-DBUILD_TYPE=%s" % self._build_type,
        "-DCOMPONENT=%s" % component,
        "-P", "cmake_install.cmake"
    ])
    command = "cd %s && %s %s" % (args_to_string([build_dir]), self._cmake_program, arg_list)
    self._run(command)
